export function listLatestOfficialContentPackages(): OfficialContentPackageMetadata[] {
  const latestByPath = new Map<string, OfficialContentPackageMetadata>();

  for (const item of packages) {
    const current = latestByPath.get(item.metadata.pathId);
    if (!current || item.metadata.packageVersion > current.packageVersion) {
      latestByPath.set(item.metadata.pathId, item.metadata);
    }
  }

  return [...latestByPath.values()]
    .sort((a, b) => a.pathId.localeCompare(b.pathId))
    .map((metadata) => ({ ...metadata }));
}

export function findOfficialContentPackage(
  pathId: string,
  packageVersion: number,
): OfficialContentPackage | null {
  const found = packages.find(
    (item) =>
      item.metadata.pathId === pathId &&
      item.metadata.packageVersion === packageVersion,
  );

  if (!found) return null;

  return {
    metadata: { ...found.metadata },
    bytes: found.bytes.slice(),
  };
}

export function officialContentPackageEtag(sha256: string): string {
  return `"sha256-${sha256}"`;
}
